async function db(){return new Promise((resolve,reject)=>{let r=indexedDB.open('tradingly_backtest_v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('runs');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
